import { useCallback } from "react";
import type {
  ActionFunctionArgs,
  HeadersFunction,
  LoaderFunctionArgs,
} from "react-router";
import { useNavigate } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Banner,
  ProgressBar,
  List,
  IndexTable,
  Badge,
  Button,
  Box,
  Divider,
  useIndexResourceState,
} from "@shopify/polaris";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";

// --- Mock Data ---

const stats = {
  revenue: { value: "$12,450", trend: "+23%", up: true },
  completions: { value: "1,247", trend: "+18%", up: true },
  conversionRate: { value: "18.3%", trend: "-2.1%", up: false },
  emailsCaptured: { value: "892", trend: "+31%", up: true },
};

const setupSteps = [
  { label: "Create your first quiz", complete: true },
  { label: "Map products to answers", complete: false },
  { label: "Publish your quiz", complete: false },
];

const quizzes = [
  {
    id: "1",
    name: "Skincare Routine Finder",
    emoji: "\uD83E\uDDF4",
    subtitle: "Beauty collection",
    status: "Live" as const,
    questions: 8,
    completions: 842,
    convRate: "22.1%",
    revenue: "$8,320",
    updated: "Mar 22, 2026",
  },
  {
    id: "2",
    name: "Gift Guide Quiz",
    emoji: "\uD83C\uDF81",
    subtitle: "Holiday campaign",
    status: "Draft" as const,
    questions: 5,
    completions: 0,
    convRate: "0%",
    revenue: "$0",
    updated: "Mar 20, 2026",
  },
  {
    id: "3",
    name: "Coffee Preference Quiz",
    emoji: "\u2615",
    subtitle: "Beverages collection",
    status: "Archived" as const,
    questions: 6,
    completions: 405,
    convRate: "14.8%",
    revenue: "$4,130",
    updated: "Feb 15, 2026",
  },
];

const statusToneMap: Record<string, "success" | "attention" | undefined> = {
  Live: "success",
  Draft: "attention",
  Archived: undefined,
};

// --- Loader / Action ---

export const loader = async ({ request }: LoaderFunctionArgs) => {
  await authenticate.admin(request);
  return null;
};

export const action = async ({ request }: ActionFunctionArgs) => {
  await authenticate.admin(request);
  return null;
};

// --- Components ---

function StatCard({
  label,
  value,
  trend,
  up,
  borderColor,
}: {
  label: string;
  value: string;
  trend: string;
  up: boolean;
  borderColor: string;
}) {
  return (
    <Card>
      <div style={{ borderTop: `3px solid ${borderColor}`, paddingTop: "4px" }}>
        <BlockStack gap="200">
          <Text as="p" variant="bodySm" tone="subdued">
            {label}
          </Text>
          <Text as="p" variant="headingXl" fontWeight="bold">
            {value}
          </Text>
          <Text
            as="p"
            variant="bodySm"
            tone={up ? "success" : "critical"}
          >
            {up ? "\u2191" : "\u2193"} {trend} vs last month
          </Text>
        </BlockStack>
      </div>
    </Card>
  );
}

function SetupChecklist({ onFinish }: { onFinish: () => void }) {
  const completedCount = setupSteps.filter((s) => s.complete).length;
  const totalCount = setupSteps.length;
  const progressPercent = Math.round((completedCount / totalCount) * 100);

  // If all steps are complete, don't show the banner
  if (completedCount === totalCount) return null;

  return (
    <Banner
      title="Complete your setup"
      tone="info"
      action={{ content: "Finish setup \u2192", onAction: onFinish }}
    >
      <BlockStack gap="300">
        <Text as="p" variant="bodySm" tone="subdued">
          {completedCount} of {totalCount} steps completed
        </Text>
        <ProgressBar progress={progressPercent} size="small" tone="primary" />
        <List type="number">
          {setupSteps.map((step, i) => (
            <List.Item key={i}>
              {step.label} {step.complete ? "\u2705" : ""}
            </List.Item>
          ))}
        </List>
      </BlockStack>
    </Banner>
  );
}

// --- Main Page ---

export default function Dashboard() {
  const navigate = useNavigate();

  const handleCreateQuiz = useCallback(() => {
    navigate("/app/quizzes/new");
  }, [navigate]);

  const handleViewAnalytics = useCallback(() => {
    navigate("/app/analytics");
  }, [navigate]);

  const handleFinishSetup = useCallback(() => {
    navigate("/app/quizzes/new");
  }, [navigate]);

  const handleEditQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}`);
    },
    [navigate],
  );

  const handlePreviewQuiz = useCallback(
    (id: string) => {
      navigate(`/app/quizzes/${id}/preview`);
    },
    [navigate],
  );

  const resourceName = { singular: "quiz", plural: "quizzes" };

  const { selectedResources, allResourcesSelected, handleSelectionChange } =
    useIndexResourceState(quizzes);

  const rowMarkup = quizzes.map(
    (
      {
        id,
        name,
        emoji,
        subtitle,
        status,
        questions,
        completions,
        convRate,
        revenue,
        updated,
      },
      index,
    ) => (
      <IndexTable.Row
        id={id}
        key={id}
        selected={selectedResources.includes(id)}
        position={index}
      >
        <IndexTable.Cell>
          <InlineStack gap="300" blockAlign="center">
            <Text as="span" variant="headingMd">
              {emoji}
            </Text>
            <BlockStack gap="050">
              <Text as="span" variant="bodyMd" fontWeight="semibold">
                {name}
              </Text>
              <Text as="span" variant="bodySm" tone="subdued">
                {subtitle}
              </Text>
            </BlockStack>
          </InlineStack>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Badge tone={statusToneMap[status]}>{status}</Badge>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {questions}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {completions.toLocaleString()}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {convRate}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodyMd" alignment="end">
            {revenue}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <Text as="span" variant="bodySm" tone="subdued">
            {updated}
          </Text>
        </IndexTable.Cell>
        <IndexTable.Cell>
          <InlineStack gap="200">
            <Button size="slim" onClick={() => handleEditQuiz(id)}>
              Edit
            </Button>
            <Button size="slim" variant="plain" onClick={() => handlePreviewQuiz(id)}>
              Preview
            </Button>
          </InlineStack>
        </IndexTable.Cell>
      </IndexTable.Row>
    ),
  );

  return (
    <Page
      title="Dashboard"
      subtitle="Welcome to QuizSnap"
      primaryAction={{
        content: "+ Create quiz",
        onAction: handleCreateQuiz,
      }}
      secondaryActions={[
        {
          content: "View analytics",
          onAction: handleViewAnalytics,
        },
      ]}
    >
      <BlockStack gap="600">
        {/* Statistics Cards Row */}
        <InlineStack gap="400" align="start" wrap={false}>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Attributed Revenue"
              value={stats.revenue.value}
              trend={stats.revenue.trend}
              up={stats.revenue.up}
              borderColor="var(--p-color-bg-fill-success)"
            />
          </div>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Quiz Completions"
              value={stats.completions.value}
              trend={stats.completions.trend}
              up={stats.completions.up}
              borderColor="var(--p-color-bg-fill-info)"
            />
          </div>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Conversion Rate"
              value={stats.conversionRate.value}
              trend={stats.conversionRate.trend}
              up={stats.conversionRate.up}
              borderColor="var(--p-color-text-emphasis)"
            />
          </div>
          <div style={{ flex: 1 }}>
            <StatCard
              label="Emails Captured"
              value={stats.emailsCaptured.value}
              trend={stats.emailsCaptured.trend}
              up={stats.emailsCaptured.up}
              borderColor="var(--p-color-bg-fill-caution)"
            />
          </div>
        </InlineStack>

        {/* Setup Checklist Banner */}
        <SetupChecklist onFinish={handleFinishSetup} />

        <Divider />

        {/* Quiz List Table */}
        <Layout>
          <Layout.Section>
            <Card padding="0">
              <BlockStack>
                <Box padding="400">
                  <Text as="h2" variant="headingMd">
                    Your Quizzes
                  </Text>
                </Box>
                <IndexTable
                  resourceName={resourceName}
                  itemCount={quizzes.length}
                  selectedItemsCount={
                    allResourcesSelected ? "All" : selectedResources.length
                  }
                  onSelectionChange={handleSelectionChange}
                  headings={[
                    { title: "Quiz" },
                    { title: "Status" },
                    { title: "Questions", alignment: "end" },
                    { title: "Completions", alignment: "end" },
                    { title: "Conv. Rate", alignment: "end" },
                    { title: "Revenue", alignment: "end" },
                    { title: "Updated" },
                    { title: "Actions" },
                  ]}
                >
                  {rowMarkup}
                </IndexTable>
              </BlockStack>
            </Card>
          </Layout.Section>
        </Layout>
      </BlockStack>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};
